window.RP_SESSION={"id":"S-bc5ace55f906","messages":[{"id":"RP-0175209","time":"2026-06-17T21:30:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"생각할 때야. 잔느. 네가 받은 그 이름이 이대로 먼지가 되어 사라지지 않게.","characters":["P-cf2651679b0b"]},{"id":"RP-0175210","time":"2026-06-17T21:30:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!마법","characters":["P-cf2651679b0b"]},{"id":"RP-0175211","time":"2026-06-17T21:30:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'잔느 듀퐁 마르탱'의 마법 판정 :\n[6, 3, 2] + [1, 6, 2, 3, 5]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-0175212","time":"2026-06-17T21:31:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엄지손가락 사이에서 불꽃이 피어오르고, 두꺼운 청단풍 시가 끄트머리에서 새빨간 불빛이 아른거리더니.","characters":["P-cf2651679b0b"]},{"id":"RP-0175213","time":"2026-06-17T21:31:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"연기가 스물스물 피어오른다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175214","time":"2026-06-17T21:32:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"선율 없는 숲속의 적막한 그루터기.","characters":["P-cf2651679b0b"]},{"id":"RP-0175215","time":"2026-06-17T21:33:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"담뱃재를 툭 털어올리는 손가락 위로 그녀의 입술이 시허연 시냇물 같은 연기를 뱉는다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175216","time":"2026-06-17T21:34:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"자른지 한 달이 되어 푸르고 거뭇거뭇하게 자란 짧은 머리카락 위로 나뭇잎 위에 얹혀 있던 낮의 빗물이 두 방울. 투둑. 떨어진다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175217","time":"2026-06-17T21:35:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그 이름을 물려준 사람에 대해 생각하던 눈빛이 뛰어들어온 싯누런 비쩍 마른 여우를 발견한다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175218","time":"2026-06-17T21:36:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"여우는 자신이 잘못 들어온 것을 깨닫지만 알 수 없는 공포에 다리가 굳어 한 발짝도 움직이지 못하고.","characters":["P-cf2651679b0b"]},{"id":"RP-0175219","time":"2026-06-17T21:37:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그녀가 눈빛을 치워주자 비틀대는 다리를 끌고 도망친다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175220","time":"2026-06-17T21:37:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그 이름을 물려준 사람.","characters":["P-cf2651679b0b"]},{"id":"RP-0175221","time":"2026-06-17T21:38:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"작고 연약한 노파의 모습이 눈에 어른거리지만 그 모습이 점차 시냇물에 비친 듯 흐릿하고 일렁이는 자신의 모습으로 바뀐다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175222","time":"2026-06-17T21:39:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"금빛 눈동자는 잠시 아무것도 보지 않는다. 이제 엘타리온이라는 이름에서는 그녀가 보이지 않는다.","characters":["P-cf2651679b0b"]},{"id":"RP-0175223","time":"2026-06-17T21:39:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잔느... 물려받은 이름. 죽은 이름이 아니라 살아갈 이름.","characters":["P-cf2651679b0b"]},{"id":"RP-0175224","time":"2026-06-17T21:39:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 고맙습니다. 할머니. \"","characters":["P-cf2651679b0b"]},{"id":"RP-0175225","time":"2026-06-17T21:39:00+09:00","room":"RP","name":"엘타리온","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cf2651679b0b"]},{"id":"RP-0175226","time":"2026-06-17T21:39:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
